//go:build integration

package postgres

import (
	"fmt"
	"testing"

	"github.com/xavidop/tobira/driver"
)

func TestDescribeAutoIncrement(t *testing.T) {
	c := openPG(t, false)
	name := fmt.Sprintf("tobira_autoinc_%d", scratchSeq.Add(1))
	mustExec(t, c, "CREATE TABLE "+name+" (s serial PRIMARY KEY, a integer GENERATED ALWAYS AS IDENTITY, "+
		"d bigint GENERATED BY DEFAULT AS IDENTITY, n bigint DEFAULT nextval('"+name+"_s_seq'), p integer, x integer DEFAULT 7)")
	t.Cleanup(func() { mustExec(t, c, "DROP TABLE IF EXISTS "+name) })
	sch, err := c.Describe(ctxT(t), driver.CollectionRef{Namespace: "public", Name: name})
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]bool{"s": true, "a": true, "d": true, "n": true, "p": false, "x": false}
	for _, f := range sch.Fields {
		if f.AutoIncrement != want[f.Name] {
			t.Errorf("field %s: AutoIncrement = %v, want %v", f.Name, f.AutoIncrement, want[f.Name])
		}
		// GENERATED ALWAYS AS IDENTITY cannot be written; BY DEFAULT can.
		if f.Generated != (f.Name == "a") {
			t.Errorf("field %s: Generated = %v, want %v", f.Name, f.Generated, f.Name == "a")
		}
	}
}
